-- ===== supabase/updates/20261126000100_m4e_founder_payout.sql =====
-- ===== idempotent copy of migrations/20261126000100_m4e_founder_payout.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4e · 0100 · Automatic CEO payout (ADR-086)
-- =============================================================================
-- Mirrors src/lib/sim/startup.ts (isValidFounderPayout, founderPayoutCents):
--   player_companies.founder_payout_bps  share of the hourly profit, whole steps of
--                                        startups.founderPayout.stepBps from 0 to maxBps
--   payout = min(floor(profit × bps / 10 000), free cash)   only for a positive profit;
--            free cash = company cash − open bills (unpaid_cents) after the hour's own bookings
--            (the same rule as company_withdraw and expand_company)
-- player_company_close_hour books the payout after all other bookings of the hour exactly like
-- company_withdraw: company cash → founder's player_cash (kind 'transfer'), then loan_withhold on
-- the founder's income. profit_cents stays unchanged (a transfer, not a cost); the amount is stored
-- in player_company_hours.founder_payout_cents. Idempotent per (company, hour) like the rest of the hour.
-- New RPC set_founder_payout(request_id, bps) → {company}. COMPANY: founder_payout_bps,
-- live.founder_payout_per_hour_cents, live.today_founder_payout_cents, hours[].founder_payout_cents.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists founder_payout_bps integer not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_founder_payout_bps_check'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_founder_payout_bps_check
      check (founder_payout_bps between 0 and 10000);
  end if;
end;
$$;
comment on column public.player_companies.founder_payout_bps is
  'Share of every profitable operating hour paid to the founder automatically (ADR-086), 0..10000 bps.';
grant select (founder_payout_bps) on public.player_companies to authenticated;

alter table public.player_company_hours add column if not exists founder_payout_cents bigint not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_company_hours_founder_payout_check'
                    and conrelid = 'public.player_company_hours'::regclass) then
    alter table public.player_company_hours add constraint player_company_hours_founder_payout_check
      check (founder_payout_cents >= 0);
  end if;
end;
$$;
comment on column public.player_company_hours.founder_payout_cents is
  'Automatic CEO payout of the hour (ADR-086): from the company cash to the founder; not part of profit_cents.';

-- ---------------------------------------------------------------------------
-- B. One operating hour as in M4c, then the CEO payout
-- ---------------------------------------------------------------------------

create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_owed    bigint;
  v_free    bigint;
  v_payout  bigint := 0;
  v_bps     integer;
  v_until   timestamptz;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision;
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level) / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  v_cogs := round((v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  v_fixed := round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  v_owed := pc.unpaid_cents + v_unpaid - v_settle;

  -- automatic CEO payout (ADR-086, founderPayoutCents): after the hour's own bookings, a share of a positive profit
  -- (rounded down) moves from the company cash to the founder's private cash like company_withdraw, never more than
  -- the free cash (cash minus open bills). A transfer, not a cost: profit_cents stays as computed above.
  v_bps := least(10000, greatest(0, coalesce(pc.founder_payout_bps, 0)));
  if v_profit > 0 and v_bps > 0 then
    select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
    v_payout := least(v_profit * v_bps / 10000, greatest(0, coalesce(v_free, 0)));
  end if;
  if v_payout > 0 then
    perform public.lock_player_accounts(pc.founder_id);
    perform public.ledger_transfer(v_acc, public.ledger_player_account(pc.founder_id, 'player_cash'), v_payout, 'transfer',
                                   'CEO-Auszahlung ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':payout', pc.founder_id);
    perform public.loan_withhold(pc.founder_id, v_payout, k || ':payout');
  end if;

  update public.player_companies
     set unpaid_cents = v_owed,
         distress = v_owed > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents, founder_payout_cents)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit, v_payout);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid,
                            'founder_payout_cents', v_payout);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083) and pays '
  'the automatic CEO payout (ADR-086); idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- C. COMPANY: payout share, payout of the last hour and of the day
-- ---------------------------------------------------------------------------
create or replace function public.company_live_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_day     timestamptz := ((public.game_now() at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin';
  v_qid     bigint := (public.current_game_quarter()).id;
  v_rev     bigint;
  v_profit  bigint;
  v_trev    bigint;
  v_tprofit bigint;
  v_qrev    bigint;
  v_qprofit bigint;
  v_tpay    bigint;
  h         public.player_company_hours;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  v_rev := h.revenue_cents;
  v_profit := h.profit_cents;
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0), coalesce(sum(x.founder_payout_cents), 0)
    into v_trev, v_tprofit, v_tpay
    from public.player_company_hours x
   where x.company_id = p_company and x.hour_start >= v_day
     and x.hour_start < ((v_day at time zone 'Europe/Berlin') + interval '1 day') at time zone 'Europe/Berlin';
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_qrev, v_qprofit
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = v_qid;
  return jsonb_build_object(
    'last_hour_at', pc.last_hour_at,
    'revenue_per_hour_cents', coalesce(v_rev, 0),
    'profit_per_hour_cents', coalesce(v_profit, 0),
    'pay_factor_bps', pc.pay_factor_bps,
    'today_revenue_cents', v_trev,
    'today_profit_cents', v_tprofit,
    'quarter_revenue_cents', v_qrev,
    'quarter_profit_cents', v_qprofit,
    -- the last closed hour in detail (ADR-083: profit coach)
    'contract_revenue_per_hour_cents', coalesce(h.contract_revenue_cents, 0),
    'demand_per_hour_cents', coalesce(h.demand_cents, 0),
    'capacity_per_hour_cents', coalesce(h.capacity_cents, 0),
    'fixed_per_hour_cents', coalesce(h.fixed_cents, 0),
    'ai_wages_per_hour_cents', coalesce(h.ai_wages_paid_cents, 0),
    'marketing_per_hour_cents', coalesce(h.marketing_cents, 0),
    -- ADR-086: automatic CEO payout of the last closed hour and of the Berlin day
    'founder_payout_per_hour_cents', coalesce(h.founder_payout_cents, 0),
    'today_founder_payout_cents', v_tpay);
end;
$$;
comment on function public.company_live_json(uuid) is
  'COMPANY.live: last closed hour (with its details, ADR-083, and the CEO payout, ADR-086), Berlin day and running quarter of a player company (ADR-072).';

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'contract_revenue_cents', x.contract_revenue_cents,
                                               'profit_cents', x.profit_cents,
                                               'founder_payout_cents', x.founder_payout_cents) order by x.hour_start), '[]'::jsonb)
    from (select h.hour_start, h.revenue_cents, h.contract_revenue_cents, h.profit_cents, h.founder_payout_cents from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;
comment on function public.company_hours_json(uuid) is 'COMPANY.hours: the last 24 closed operating hours, oldest first.';

-- company_state as in M4c plus the CEO payout share (ADR-086)
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
  v_mf     double precision;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  -- the estimate describes the market the company reaches (ADR-083)
  v_mf := public.company_market_factor(pc.tier, pc.expansion_level);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents * v_mf
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents * v_mf
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', public.company_max_employees(p_company),
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', round((v_team ->> 'capacity_cents')::bigint * public.company_capacity_factor(pc.expansion_level))::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 6),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object(
         'banner', pc.banner,
         -- ADR-083: price strategy, contract work, expansion
         'price_level', pc.price_level,
         'contract_work', pc.contract_work,
         'expansion_level', pc.expansion_level,
         'can_expand', public.company_can_expand(pc.tier),
         'expansion_cost_cents', case when public.company_can_expand(pc.tier)
                                      then public.company_expansion_cost_cents(pc.expansion_level) end,
         'market_factor', round(v_mf::numeric, 4),
         -- ADR-086: share of the hourly profit paid to the founder automatically
         'founder_payout_bps', pc.founder_payout_bps);
end;
$$;

-- ---------------------------------------------------------------------------
-- D. RPC: payout share (founder only)
-- ---------------------------------------------------------------------------
create or replace function public.set_founder_payout(p_request_id uuid, p_bps integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_step    integer := greatest(1, public.config_double('startups', '{founderPayout,stepBps}', 500)::integer);
  v_max     integer := least(10000, public.config_double('startups', '{founderPayout,maxBps}', 10000)::integer);
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_bps is null or p_bps < 0 or p_bps > v_max or p_bps % v_step <> 0 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_founder_payout');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies set founder_payout_bps = p_bps where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.set_founder_payout(uuid, integer) is
  'RPC (founder): share of the hourly profit paid out automatically, whole steps of startups.founderPayout (ADR-086); '
  'errors company_not_found, invalid_argument.';

-- ---------------------------------------------------------------------------
-- E. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.player_company_close_hour(uuid, timestamptz)', 'public.company_live_json(uuid)', 'public.company_hours_json(uuid)',
    'public.company_state(uuid)', 'public.set_founder_payout(uuid, integer)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.set_founder_payout(uuid, integer) to authenticated;
end;
$$;

-- ===== supabase/updates/20261127000100_m4f_social.sql =====
-- ===== idempotent copy of migrations/20261127000100_m4f_social.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4f · 0100 · Friends feed and in-app notifications (ADR-088)
-- =============================================================================
-- Feed items are written by AFTER triggers on the tables of the existing write paths, so no
-- RPC changes its behaviour (a rolled back action leaves no item). Kinds and payloads
-- (the client renders the German text from kind + payload):
--   level_up {level}                     profiles.level reaches a multiple of social.feed.levelEvery
--   big_trade {ticker, security_name, profit_cents, profit_bps}
--                                        trades: a fill that realises ≥ bigTradeMinProfitCents and ≥ bigTradeMinBps
--   company_founded {name, tier}         player_companies insert
--   company_upgraded {name, tier}        player_companies.tier changes (not to 'ag')
--   company_ipo {name, ticker}           player_companies.tier becomes 'ag' (IPO subscription ended listed)
--   company_expanded {name, level}       player_companies.expansion_level rises
--   art_won {title, code, price_cents}   artwork_sales insert ≥ artMinPriceCents (gallery and player auctions)
--   art_created {title, code}            artworks insert of a player artwork
--   home_bought {tier}                   player_homes.tier set / changed
--   car_bought {car_key, price_cents}    player_cars insert ≥ carMinPriceCents
--   job_started {company_name, title, title_key}  player_jobs insert from a signed contract
--   streak {days}                        login_streaks.current_streak reaches a value of streakMilestones
--   friends_now {other_nickname}         friendships pending → accepted (one item per side)
--   league_won {week_start, growth_bps}  posted by league_close (migration 0200)
-- Reactions: feed_reactions (one per item and player), RPC react_feed toggles.
-- RPCs: get_feed(before, limit) -> {items: [FEED_ITEM], next_before}, react_feed(request_id, item_id) -> {item},
--       get_notifications(limit) -> {items, unread}, mark_notifications_read(ids) -> {unread}.
-- Notifications (in-app, preferences respected): feed_reaction, art_outbid, job_application (league_result: 0200).
-- Error: feed_item_not_found (react_feed on an item that does not exist or is not visible).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.feed_items add column if not exists dedupe_key text;
create unique index if not exists feed_items_dedupe_uq on public.feed_items (dedupe_key);
create index if not exists feed_items_actor_id_idx on public.feed_items (actor_id, id desc);
comment on column public.feed_items.dedupe_key is 'Optional unique key: the same event never posts twice (ADR-088).';

create table if not exists public.feed_reactions (
  item_id    bigint not null references public.feed_items (id) on delete cascade,
  player_id  uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (item_id, player_id)
);
alter table public.feed_reactions enable row level security;
create index if not exists feed_reactions_player_idx on public.feed_reactions (player_id);
revoke all on public.feed_reactions from public, anon, authenticated;
grant all on public.feed_reactions to service_role;
comment on table public.feed_reactions is 'One reaction ("gefällt mir") per feed item and player (ADR-088). Internal (RPCs).';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('feed_reaction', 'social', 'Reaktion im Feed', 'Jemand hat auf deinen Beitrag im Freundes-Feed reagiert.',
        'notif_feed', true, false, false, 285),
       ('league_result', 'social', 'Liga-Ergebnis', 'Die Wochenliga ist ausgewertet.', 'notif_trophy', true, false, false, 290),
       ('art_outbid', 'social', 'Überboten', 'Jemand hat dein Gebot auf ein Kunstwerk überboten.', 'notif_bell', true, true,
        false, 295),
       ('job_application', 'company', 'Neue Bewerbung', 'Jemand hat sich auf eine Stelle deiner Firma beworben.',
        'notif_briefcase', true, false, false, 225)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- One feed item of an active player (visibility friends); a known dedupe key posts nothing
create or replace function public.feed_post(p_actor uuid, p_kind text, p_payload jsonb, p_dedupe text default null)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id bigint;
begin
  if p_actor is null or p_kind is null
     or not exists (select 1 from public.profiles p where p.id = p_actor and not p.is_deactivated) then
    return null;
  end if;
  insert into public.feed_items (actor_id, kind, visibility, payload, dedupe_key)
  values (p_actor, p_kind, 'friends', coalesce(p_payload, '{}'::jsonb), p_dedupe)
  on conflict (dedupe_key) do nothing
  returning id into v_id;
  return v_id;
end;
$$;
comment on function public.feed_post(uuid, text, jsonb, text) is
  'Internal: posts a friends feed item (ADR-088); p_dedupe makes retries harmless.';

-- In-app notification unless the player switched the type off (missing preference: the type's
-- default; mandatory types always). A known (player, dedupe key) inserts nothing.
create or replace function public.social_notify(p_player uuid, p_type text, p_title text, p_body text, p_payload jsonb,
                                                p_link text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.notification_types;
begin
  select * into t from public.notification_types x where x.key = p_type;
  if t.key is null or p_player is null
     or not exists (select 1 from public.profiles p where p.id = p_player and not p.is_deactivated) then
    return;
  end if;
  if not t.is_mandatory
     and not coalesce((select np.in_app_enabled from public.notification_preferences np
                        where np.player_id = p_player and np.type_key = p_type), t.default_in_app, true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, p_type, left(p_title, 200), left(p_body, 500), coalesce(p_payload, '{}'::jsonb), p_link, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;
comment on function public.social_notify(uuid, text, text, text, jsonb, text, text) is
  'Internal: in-app notification respecting notification_preferences (ADR-088).';

-- Short German description of a feed item (body of the reaction notification)
create or replace function public.feed_item_label(p_kind text, p_payload jsonb)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_kind
    when 'level_up' then 'Level ' || coalesce(p_payload ->> 'level', '?') || ' erreicht'
    when 'big_trade' then 'Gewinn mit ' || coalesce(p_payload ->> 'ticker', 'einer Aktie')
    when 'company_founded' then coalesce(p_payload ->> 'name', 'Firma') || ' gegründet'
    when 'company_upgraded' then coalesce(p_payload ->> 'name', 'Firma') || ' aufgestiegen'
    when 'company_ipo' then coalesce(p_payload ->> 'name', 'Firma') || ' an der Börse'
    when 'company_expanded' then coalesce(p_payload ->> 'name', 'Firma') || ' erweitert'
    when 'art_won' then 'Kunstwerk „' || coalesce(p_payload ->> 'title', '?') || '“ ersteigert'
    when 'art_created' then 'Kunstwerk „' || coalesce(p_payload ->> 'title', '?') || '“ gemalt'
    when 'home_bought' then 'Neues Zuhause'
    when 'car_bought' then 'Neues Auto'
    when 'job_started' then 'Neuer Job bei ' || coalesce(p_payload ->> 'company_name', '?')
    when 'streak' then coalesce(p_payload ->> 'days', '?') || ' Tage in Folge dabei'
    when 'league_won' then 'Wochenliga gewonnen'
    when 'friends_now' then 'Jetzt befreundet mit ' || coalesce(p_payload ->> 'other_nickname', '?')
    else 'Beitrag im Feed'
  end;
$$;

-- Accepted friends of a player
create or replace function public.friend_ids(p_player uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select case when f.requester_id = p_player then f.addressee_id else f.requester_id end
    from public.friendships f
   where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id);
$$;

-- FEED_ITEM from the point of view of p_viewer
create or replace function public.feed_item_json(p_item bigint, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id',         fi.id,
    'kind',       fi.kind,
    'payload',    fi.payload,
    'created_at', fi.created_at,
    'is_me',      fi.actor_id = p_viewer,
    'actor',      jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'level', p.level),
    'reactions',  (select count(*) from public.feed_reactions r where r.item_id = fi.id)::integer,
    'reacted',    exists (select 1 from public.feed_reactions r where r.item_id = fi.id and r.player_id = p_viewer))
    from public.feed_items fi join public.profiles p on p.id = fi.actor_id
   where fi.id = p_item;
$$;

-- ---------------------------------------------------------------------------
-- C. Feed triggers (each fires only for the real event of its write path)
-- ---------------------------------------------------------------------------
create or replace function public.feed_on_level()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_every integer := greatest(1, public.config_double('social', '{feed,levelEvery}', 5)::integer);
  v_level integer := (new.level / v_every) * v_every;
begin
  if v_level > old.level and v_level >= v_every then
    perform public.feed_post(new.id, 'level_up', jsonb_build_object('level', v_level),
                             'level_up:' || new.id::text || ':' || v_level::text);
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_level on public.profiles;
create trigger feed_on_level after update of level on public.profiles
  for each row when (new.level > old.level) execute function public.feed_on_level();

-- profit_bps = realised profit / cost basis of the sold part (gross - fee - profit)
create or replace function public.feed_on_trade()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cost bigint := new.gross_cents - new.fee_cents - new.realized_pnl_cents;
  v_bps  bigint;
  s      public.securities;
begin
  if new.counterparty = 'issuer' or v_cost <= 0
     or new.realized_pnl_cents < public.config_bigint('social', '{feed,bigTradeMinProfitCents}', 100000) then
    return null;
  end if;
  v_bps := public.div_round_half_even(new.realized_pnl_cents::numeric * 10000, v_cost);
  if v_bps < public.config_bigint('social', '{feed,bigTradeMinBps}', 1500) then
    return null;
  end if;
  select * into s from public.securities x where x.id = new.security_id;
  perform public.feed_post(new.player_id, 'big_trade',
    jsonb_build_object('ticker', s.ticker, 'security_name', s.name, 'profit_cents', new.realized_pnl_cents, 'profit_bps', v_bps),
    'big_trade:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_trade on public.trades;
create trigger feed_on_trade after insert on public.trades
  for each row when (new.realized_pnl_cents is not null and new.realized_pnl_cents > 0)
  execute function public.feed_on_trade();

create or replace function public.feed_on_company()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  c public.companies;
begin
  select * into c from public.companies x where x.id = new.company_id;
  if tg_op = 'INSERT' then
    perform public.feed_post(new.founder_id, 'company_founded', jsonb_build_object('name', c.name, 'tier', new.tier),
                             'company_founded:' || new.company_id::text);
    return null;
  end if;
  if new.tier is distinct from old.tier then
    if new.tier = 'ag' then
      perform public.feed_post(new.founder_id, 'company_ipo', jsonb_build_object('name', c.name, 'ticker', c.ticker),
                               'company_ipo:' || new.company_id::text);
    else
      perform public.feed_post(new.founder_id, 'company_upgraded', jsonb_build_object('name', c.name, 'tier', new.tier),
                               'company_upgraded:' || new.company_id::text || ':' || new.tier);
    end if;
  end if;
  if new.expansion_level > old.expansion_level then
    perform public.feed_post(new.founder_id, 'company_expanded', jsonb_build_object('name', c.name, 'level', new.expansion_level),
                             'company_expanded:' || new.company_id::text || ':' || new.expansion_level::text);
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_company_insert on public.player_companies;
create trigger feed_on_company_insert after insert on public.player_companies
  for each row execute function public.feed_on_company();
drop trigger if exists feed_on_company_update on public.player_companies;
create trigger feed_on_company_update after update of tier, expansion_level on public.player_companies
  for each row when (new.tier is distinct from old.tier or new.expansion_level > old.expansion_level)
  execute function public.feed_on_company();

create or replace function public.feed_on_art_sale()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  a public.artworks;
begin
  if new.price_cents < public.config_bigint('social', '{feed,artMinPriceCents}', 1000000) then
    return null;
  end if;
  select * into a from public.artworks x where x.id = new.artwork_id;
  perform public.feed_post(new.buyer_id, 'art_won',
    jsonb_build_object('title', a.title, 'code', public.artwork_code(a.serial), 'price_cents', new.price_cents),
    'art_won:' || new.auction_id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_art_sale on public.artwork_sales;
create trigger feed_on_art_sale after insert on public.artwork_sales
  for each row execute function public.feed_on_art_sale();

create or replace function public.feed_on_art_created()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.creator_id, 'art_created',
    jsonb_build_object('title', new.title, 'code', public.artwork_code(new.serial)), 'art_created:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_art_created on public.artworks;
create trigger feed_on_art_created after insert on public.artworks
  for each row when (new.origin = 'player' and new.creator_id is not null) execute function public.feed_on_art_created();

create or replace function public.feed_on_home()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.player_id, 'home_bought', jsonb_build_object('tier', new.tier), null);
  return null;
end;
$$;
drop trigger if exists feed_on_home_insert on public.player_homes;
create trigger feed_on_home_insert after insert on public.player_homes
  for each row when (new.tier is not null) execute function public.feed_on_home();
drop trigger if exists feed_on_home_update on public.player_homes;
create trigger feed_on_home_update after update of tier on public.player_homes
  for each row when (new.tier is not null and new.tier is distinct from old.tier) execute function public.feed_on_home();

create or replace function public.feed_on_car()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.price_paid_cents >= public.config_bigint('social', '{feed,carMinPriceCents}', 10000000) then
    perform public.feed_post(new.player_id, 'car_bought', jsonb_build_object('car_key', new.car_key, 'price_cents', new.price_paid_cents),
                             'car_bought:' || new.id::text);
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_car on public.player_cars;
create trigger feed_on_car after insert on public.player_cars
  for each row execute function public.feed_on_car();

-- title as stored (custom title or the AI title key), title_key for translation (null for custom titles)
create or replace function public.feed_on_job()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.player_id, 'job_started',
    jsonb_build_object('company_name', (select c.name from public.companies c where c.id = new.company_id),
                       'title', new.title, 'title_key', new.title_key),
    'job_started:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_job on public.player_jobs;
create trigger feed_on_job after insert on public.player_jobs
  for each row when (new.application_id is not null) execute function public.feed_on_job();

create or replace function public.feed_on_streak()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from jsonb_array_elements_text(coalesce(public.config_jsonb('social', '{feed,streakMilestones}'),
                                                              '[7, 30, 100, 365]'::jsonb)) m
              where m.value ~ '^[0-9]+$' and m.value::integer = new.current_streak) then
    perform public.feed_post(new.player_id, 'streak', jsonb_build_object('days', new.current_streak),
                             'streak:' || new.player_id::text || ':' || new.current_streak::text || ':'
                             || coalesce(new.last_login_day::text, ''));
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_streak on public.login_streaks;
create trigger feed_on_streak after update of current_streak on public.login_streaks
  for each row when (new.current_streak > old.current_streak) execute function public.feed_on_streak();

create or replace function public.feed_on_friendship()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.requester_id, 'friends_now',
    jsonb_build_object('other_nickname', (select p.nickname from public.profiles p where p.id = new.addressee_id)),
    'friends_now:' || new.id::text || ':' || new.requester_id::text);
  perform public.feed_post(new.addressee_id, 'friends_now',
    jsonb_build_object('other_nickname', (select p.nickname from public.profiles p where p.id = new.requester_id)),
    'friends_now:' || new.id::text || ':' || new.addressee_id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_friendship on public.friendships;
create trigger feed_on_friendship after update of status on public.friendships
  for each row when (new.status = 'accepted' and old.status is distinct from 'accepted')
  execute function public.feed_on_friendship();

-- ---------------------------------------------------------------------------
-- D. Notification triggers
-- ---------------------------------------------------------------------------
-- The previous highest bidder of an artwork auction (not when the leader raises the own bid)
create or replace function public.notify_on_outbid()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  a      public.artworks;
  v_nick text;
begin
  select * into a from public.artworks x where x.id = new.artwork_id;
  select p.nickname into v_nick from public.profiles p where p.id = new.leader_id;
  perform public.social_notify(old.leader_id, 'art_outbid', v_nick || ' hat dich überboten',
    '„' || a.title || '“ (' || public.artwork_code(a.serial) || '): neues Gebot ' || public.format_eur(new.current_cents),
    jsonb_build_object('auction_id', new.id, 'artwork_id', a.id, 'code', public.artwork_code(a.serial), 'title', a.title,
                       'amount_cents', new.current_cents, 'nickname', v_nick),
    '/artworks', 'art_outbid:' || new.id::text || ':' || new.bids::text);
  return null;
end;
$$;
drop trigger if exists notify_on_outbid on public.artwork_auctions;
create trigger notify_on_outbid after update of leader_id on public.artwork_auctions
  for each row when (old.leader_id is not null and new.leader_id is not null and new.leader_id <> old.leader_id)
  execute function public.notify_on_outbid();

-- The founder of a player company receives every new application to one of its postings
create or replace function public.notify_on_application()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_founder uuid;
  v_title   text;
  v_nick    text;
begin
  select pc.founder_id, coalesce(jp.title, jp.title_key) into v_founder, v_title
    from public.job_postings jp
    join public.player_companies pc on pc.company_id = jp.company_id and pc.status = 'active'
   where jp.id = new.posting_id and not jp.is_ai;
  if v_founder is null or v_founder = new.player_id then
    return null;
  end if;
  select p.nickname into v_nick from public.profiles p where p.id = new.player_id;
  perform public.social_notify(v_founder, 'job_application', v_nick || ' hat sich beworben', 'Stelle: ' || v_title,
    jsonb_build_object('application_id', new.id, 'posting_id', new.posting_id, 'nickname', v_nick, 'title', v_title),
    '/company', 'job_application:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists notify_on_application on public.job_applications;
create trigger notify_on_application after insert on public.job_applications
  for each row execute function public.notify_on_application();

-- ---------------------------------------------------------------------------
-- E. RPCs: feed
-- ---------------------------------------------------------------------------
-- My items and those of accepted friends, newest first, keyset pagination by id
create or replace function public.get_feed(p_before bigint default null, p_limit integer default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_limit  integer := least(50, greatest(1, coalesce(p_limit,
                        public.config_double('social', '{feed,pageSize}', 30)::integer)));
  v_actors uuid[];
  v_ids    bigint[];
  v_more   boolean;
begin
  select array_agg(x) into v_actors from (select v_player as x union select public.friend_ids(v_player)) f;
  select coalesce(array_agg(x.id order by x.id desc), '{}') into v_ids
    from (select fi.id
            from public.feed_items fi join public.profiles p on p.id = fi.actor_id
           where fi.actor_id = any (v_actors) and not p.is_deactivated
             and (p_before is null or fi.id < p_before)
           order by fi.id desc
           limit v_limit + 1) x;
  v_more := coalesce(array_length(v_ids, 1), 0) > v_limit;
  if v_more then
    v_ids := v_ids[1:v_limit];
  end if;
  return jsonb_build_object(
    'items', coalesce((select jsonb_agg(public.feed_item_json(i.id, v_player) order by i.id desc) from unnest(v_ids) i(id)),
                      '[]'::jsonb),
    'next_before', case when v_more then v_ids[v_limit] end);
end;
$$;
comment on function public.get_feed(bigint, integer) is
  'RPC: friends feed (own items and accepted friends), newest first; p_before = keyset cursor (ADR-088).';

-- Toggles my reaction; the actor is notified once per (item, reactor)
create or replace function public.react_feed(p_request_id uuid, p_item_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  it       public.feed_items;
  v_nick   text;
begin
  v_player := public.require_player();
  if p_request_id is null or p_item_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'react_feed');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  select fi.* into it
    from public.feed_items fi join public.profiles p on p.id = fi.actor_id
   where fi.id = p_item_id and not p.is_deactivated;
  if it.id is null or (it.actor_id <> v_player and it.actor_id not in (select public.friend_ids(v_player))) then
    perform public.api_error('feed_item_not_found');
  end if;
  delete from public.feed_reactions r where r.item_id = it.id and r.player_id = v_player;
  if not found then
    insert into public.feed_reactions (item_id, player_id) values (it.id, v_player) on conflict do nothing;
    if it.actor_id <> v_player then
      select p.nickname into v_nick from public.profiles p where p.id = v_player;
      perform public.social_notify(it.actor_id, 'feed_reaction', v_nick || ' gefällt dein Beitrag',
        public.feed_item_label(it.kind, it.payload),
        jsonb_build_object('item_id', it.id, 'kind', it.kind, 'nickname', v_nick),
        '/friends', 'feed_reaction:' || it.id::text || ':' || v_player::text);
    end if;
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('item', public.feed_item_json(it.id, v_player)));
end;
$$;
comment on function public.react_feed(uuid, bigint) is
  'RPC: toggles the caller''s reaction on a visible feed item -> {item} (ADR-088). Error feed_item_not_found.';

-- ---------------------------------------------------------------------------
-- F. RPCs: notifications
-- ---------------------------------------------------------------------------
create or replace function public.get_notifications(p_limit integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_limit  integer := least(100, greatest(1, coalesce(p_limit, 30)));
begin
  return jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.id, 'type_key', x.type_key, 'title', x.title, 'body', x.body, 'link', x.link,
                                          'payload', x.payload, 'created_at', x.created_at, 'read_at', x.read_at)
                       order by x.created_at desc, x.id)
        from (select n.* from public.notifications n
               where n.player_id = v_player and (n.expires_at is null or n.expires_at > now())
               order by n.created_at desc, n.id limit v_limit) x), '[]'::jsonb),
    'unread', (select count(*) from public.notifications n
                where n.player_id = v_player and n.read_at is null and (n.expires_at is null or n.expires_at > now()))::integer);
end;
$$;
comment on function public.get_notifications(integer) is
  'RPC: the caller''s notifications (not expired), newest first, and the unread count (ADR-088).';

-- null = all; already read rows keep their read_at (idempotent)
create or replace function public.mark_notifications_read(p_ids uuid[] default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
begin
  update public.notifications n set read_at = now()
   where n.player_id = v_player and n.read_at is null and (p_ids is null or n.id = any (p_ids));
  return jsonb_build_object('unread', (select count(*) from public.notifications n
                                        where n.player_id = v_player and n.read_at is null
                                          and (n.expires_at is null or n.expires_at > now()))::integer);
end;
$$;
comment on function public.mark_notifications_read(uuid[]) is
  'RPC: marks the caller''s notifications (all or p_ids) as read -> {unread} (ADR-088).';

-- ---------------------------------------------------------------------------
-- G. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.feed_post(uuid, text, jsonb, text)', 'public.social_notify(uuid, text, text, text, jsonb, text, text)',
    'public.feed_item_label(text, jsonb)', 'public.friend_ids(uuid)', 'public.feed_item_json(bigint, uuid)',
    'public.feed_on_level()', 'public.feed_on_trade()', 'public.feed_on_company()', 'public.feed_on_art_sale()',
    'public.feed_on_art_created()', 'public.feed_on_home()', 'public.feed_on_car()', 'public.feed_on_job()',
    'public.feed_on_streak()', 'public.feed_on_friendship()', 'public.notify_on_outbid()', 'public.notify_on_application()',
    'public.get_feed(bigint, integer)', 'public.react_feed(uuid, bigint)', 'public.get_notifications(integer)',
    'public.mark_notifications_read(uuid[])'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_feed(bigint, integer)', 'public.react_feed(uuid, bigint)', 'public.get_notifications(integer)',
    'public.mark_notifications_read(uuid[])'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261127000200_m4f_league.sql =====
-- ===== idempotent copy of migrations/20261127000200_m4f_league.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4f · 0200 · Weekly league (ADR-089)
-- =============================================================================
-- Season = Berlin calendar week (Monday 00:00 to next Monday 00:00 Europe/Berlin, game time).
-- Every active player gets an entry and a baseline the first time a season is refreshed after
-- they exist: start_net_worth_cents = net worth as in the rich list (rich_list_entries()).
--   growth_bps = round_half_even((current - start - net_inflow) * 10 000 / max(start, social.league.minBaselineCents))
-- net_inflow_cents counts free money (vault basic income, daily reward cash) via triggers on
-- vault_claims and daily_reward_claims; wages, company payouts, trading and art are performance.
-- public.social_run_due() (called by run_due_jobs every minute):
--   1. closes due seasons (final recompute, status finished, winner_id = rank 1, feed item league_won,
--      notification league_result to every ranked participant),
--   2. ensures the current season, refreshes it every social.league.updateEveryMinutes,
--   3. deletes feed items older than social.feed.keepDays (with the refresh).
-- RPC get_league(scope 'all' | 'friends', week 'current' | 'last'); get_player_card gains trophies.
-- Errors: invalid_argument (unknown scope or week).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.league_seasons add column if not exists refreshed_at timestamptz;
comment on column public.league_seasons.refreshed_at is 'Game time of the last standings refresh (ADR-089); null = never.';

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- Monday (Europe/Berlin) of the week that contains p_at
create or replace function public.league_week_start(p_at timestamptz)
returns date
language sql
stable
set search_path = ''
as $$
  select (p_at at time zone 'Europe/Berlin')::date - (extract(isodow from (p_at at time zone 'Europe/Berlin'))::integer - 1);
$$;

-- "+3,40 %" / "-0,25 %"
create or replace function public.format_growth_bps(p_bps bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select case when p_bps < 0 then '-' else '+' end
      || replace(to_char(abs(p_bps) / 100.0, 'FM999999990.00'), '.', ',') || ' %';
$$;

-- The season of the week that contains p_at (created as active if missing)
create or replace function public.league_ensure_season(p_at timestamptz)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_week date := public.league_week_start(p_at);
  v_id   uuid;
begin
  insert into public.league_seasons (week_start, starts_at, ends_at, status)
  values (v_week, v_week::timestamp at time zone 'Europe/Berlin', (v_week + 7)::timestamp at time zone 'Europe/Berlin', 'active')
  on conflict (week_start) do nothing;
  select s.id into v_id from public.league_seasons s where s.week_start = v_week;
  return v_id;
end;
$$;

-- Free money of a player counts as inflow of every open season that has started
create or replace function public.league_add_inflow(p_player uuid, p_cents bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_player is null or coalesce(p_cents, 0) = 0 then
    return;
  end if;
  update public.league_entry_baselines b
     set net_inflow_cents = b.net_inflow_cents + p_cents, updated_at = now()
    from public.league_seasons s
   where s.id = b.season_id and b.player_id = p_player and s.status <> 'finished' and s.starts_at <= public.game_now();
end;
$$;

-- Net worth, growth and rank of one season. p_add_new: active players without an entry join
-- with their current net worth as baseline. Returns the number of ranked entries.
create or replace function public.league_refresh(p_season uuid, p_add_new boolean default true)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_min   bigint := greatest(1, public.config_bigint('social', '{league,minBaselineCents}', 1000000));
  v_count integer;
begin
  with nw as materialized (
    select e.entity_id as player_id, e.net_worth_cents as nw
      from public.rich_list_entries() e where e.entity_kind = 'player'
  ), new_entries as (
    insert into public.league_entries (season_id, player_id)
    select p_season, n.player_id from nw n
     where p_add_new
       and not exists (select 1 from public.league_entries x where x.season_id = p_season and x.player_id = n.player_id)
    on conflict do nothing
    returning player_id
  ), new_baselines as (
    insert into public.league_entry_baselines (season_id, player_id, start_net_worth_cents, current_net_worth_cents)
    select p_season, x.player_id, n.nw, n.nw from new_entries x join nw n on n.player_id = x.player_id
    on conflict do nothing
    returning player_id
  )
  update public.league_entry_baselines b
     set current_net_worth_cents = n.nw, updated_at = now()
    from nw n
   where b.season_id = p_season and b.player_id = n.player_id and b.current_net_worth_cents <> n.nw;

  update public.league_entries e
     set growth_bps = greatest(-2000000000, least(2000000000, public.div_round_half_even(
                        (b.current_net_worth_cents - b.start_net_worth_cents - b.net_inflow_cents)::numeric * 10000,
                        greatest(b.start_net_worth_cents, v_min))))::integer,
         updated_at = now()
    from public.league_entry_baselines b
   where e.season_id = p_season and b.season_id = e.season_id and b.player_id = e.player_id;

  -- rank: growth, then the earlier account, then nickname; deactivated players are not ranked
  update public.league_entries e set rank = r.rk
    from (select x.player_id,
                 (row_number() over (order by x.growth_bps desc, p.created_at, lower(p.nickname), p.id))::integer as rk
            from public.league_entries x join public.profiles p on p.id = x.player_id
           where x.season_id = p_season and not p.is_deactivated) r
   where e.season_id = p_season and e.player_id = r.player_id and e.rank is distinct from r.rk;
  update public.league_entries e set rank = null
   where e.season_id = p_season and e.rank is not null
     and exists (select 1 from public.profiles p where p.id = e.player_id and p.is_deactivated);

  update public.league_seasons set refreshed_at = public.game_now(), updated_at = now() where id = p_season;
  select count(*) into v_count from public.league_entries e where e.season_id = p_season and e.rank is not null;
  return v_count;
end;
$$;

-- Final recompute, winner, feed item league_won, league_result for every ranked participant
create or replace function public.league_close(p_season uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  s        public.league_seasons;
  v_count  integer;
  v_winner uuid;
  v_growth integer;
  r        record;
begin
  select * into s from public.league_seasons x where x.id = p_season for update;
  if s.id is null or s.status = 'finished' then
    return null;
  end if;
  v_count := public.league_refresh(p_season, false);
  select e.player_id, e.growth_bps into v_winner, v_growth
    from public.league_entries e where e.season_id = p_season and e.rank = 1;
  update public.league_seasons set status = 'finished', winner_id = v_winner, updated_at = now() where id = p_season;
  if v_winner is not null then
    perform public.feed_post(v_winner, 'league_won', jsonb_build_object('week_start', s.week_start, 'growth_bps', v_growth),
                             'league_won:' || p_season::text);
  end if;
  for r in select e.player_id, e.rank, e.growth_bps from public.league_entries e
            where e.season_id = p_season and e.rank is not null order by e.rank
  loop
    perform public.social_notify(r.player_id, 'league_result',
      case when r.rank = 1 then 'Du hast die Wochenliga gewonnen!' else 'Wochenliga: Platz ' || r.rank end,
      'Platz ' || r.rank || ' von ' || v_count || ' · ' || public.format_growth_bps(r.growth_bps),
      jsonb_build_object('week_start', s.week_start, 'rank', r.rank, 'of', v_count, 'growth_bps', r.growth_bps),
      '/friends', 'league_result:' || p_season::text);
  end loop;
  return jsonb_build_object('week_start', s.week_start, 'entries', v_count, 'winner', v_winner);
end;
$$;

-- Periodic social work, called by run_due_jobs every minute (throttled here)
create or replace function public.social_run_due()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := public.game_now();
  v_closed  jsonb := '[]'::jsonb;
  v_season  uuid;
  v_last    timestamptz;
  v_count   integer;
  v_deleted bigint := 0;
  q         record;
begin
  for q in select s.id from public.league_seasons s
            where s.status <> 'finished' and s.ends_at <= v_now order by s.ends_at limit 8
  loop
    v_closed := v_closed || coalesce(public.league_close(q.id), 'null'::jsonb);
  end loop;
  v_season := public.league_ensure_season(v_now);
  select s.refreshed_at into v_last from public.league_seasons s where s.id = v_season;
  if v_last is not null
     and v_last > v_now - make_interval(secs => greatest(1, public.config_double('social', '{league,updateEveryMinutes}', 10)) * 60 - 5) then
    return jsonb_build_object('closed', v_closed, 'skipped', 'recent');
  end if;
  v_count := public.league_refresh(v_season, true);
  delete from public.feed_items fi
   where fi.created_at < now() - make_interval(days => greatest(1, public.config_double('social', '{feed,keepDays}', 30))::integer);
  get diagnostics v_deleted = row_count;
  return jsonb_build_object('closed', v_closed, 'league_entries', v_count, 'feed_deleted', v_deleted);
end;
$$;

-- ---------------------------------------------------------------------------
-- C. Free money as league inflow
-- ---------------------------------------------------------------------------
create or replace function public.league_on_vault_claim()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.league_add_inflow(new.player_id, new.amount_cents);
  return null;
end;
$$;
drop trigger if exists league_on_vault_claim on public.vault_claims;
create trigger league_on_vault_claim after insert on public.vault_claims
  for each row when (new.amount_cents > 0) execute function public.league_on_vault_claim();

create or replace function public.league_on_daily_reward()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.league_add_inflow(new.player_id, new.cash_cents);
  return null;
end;
$$;
drop trigger if exists league_on_daily_reward on public.daily_reward_claims;
create trigger league_on_daily_reward after insert on public.daily_reward_claims
  for each row when (new.cash_cents > 0) execute function public.league_on_daily_reward();

-- ---------------------------------------------------------------------------
-- D. RPC get_league
-- ---------------------------------------------------------------------------
create or replace function public.get_league(p_scope text default 'all', p_week text default 'current')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_now     timestamptz := public.game_now();
  v_current date := public.league_week_start(v_now);
  v_week    date;
  s         public.league_seasons;
  v_entries jsonb;
  v_me      jsonb;
  v_last    jsonb;
begin
  if p_scope is null or p_scope not in ('all', 'friends') or p_week is null or p_week not in ('current', 'last') then
    perform public.api_error('invalid_argument');
  end if;
  v_week := case when p_week = 'last' then v_current - 7 else v_current end;
  select * into s from public.league_seasons x where x.week_start = v_week;

  with x as (
    select e.player_id, e.growth_bps, p.nickname, p.tag, p.avatar_key, p.level,
           (row_number() over (order by e.rank nulls last, e.growth_bps desc, p.created_at, lower(p.nickname), p.id))::integer as rk
      from public.league_entries e join public.profiles p on p.id = e.player_id
     where e.season_id = s.id and not p.is_deactivated
       and (p_scope = 'all' or e.player_id = v_player or e.player_id in (select public.friend_ids(v_player)))
  )
  select coalesce(jsonb_agg(jsonb_build_object('rank', x.rk, 'nickname', x.nickname, 'tag', x.tag, 'avatar_key', x.avatar_key,
                                               'level', x.level, 'growth_bps', x.growth_bps, 'is_me', x.player_id = v_player)
                            order by x.rk) filter (where x.rk <= 100), '[]'::jsonb),
         (select jsonb_build_object('rank', y.rk, 'growth_bps', y.growth_bps) from x y where y.player_id = v_player)
    into v_entries, v_me
    from x;

  select jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'growth_bps', e.growth_bps,
                            'week_start', ls.week_start)
    into v_last
    from public.league_seasons ls
    join public.profiles p on p.id = ls.winner_id
    join public.league_entries e on e.season_id = ls.id and e.player_id = ls.winner_id
   where ls.status = 'finished' and ls.week_start < v_current and not p.is_deactivated
   order by ls.week_start desc
   limit 1;

  return jsonb_build_object(
    'season', jsonb_build_object(
      'week_start', v_week,
      'starts_at',  coalesce(s.starts_at, v_week::timestamp at time zone 'Europe/Berlin'),
      'ends_at',    coalesce(s.ends_at, (v_week + 7)::timestamp at time zone 'Europe/Berlin'),
      'status',     coalesce(s.status::text, case when p_week = 'last' then 'finished' else 'active' end)),
    'entries', v_entries,
    'me', v_me,
    'last_winner', v_last);
end;
$$;
comment on function public.get_league(text, text) is
  'RPC: weekly league standings (ADR-089); scope all | friends (me + accepted friends, re-numbered), week current | last.';

-- ---------------------------------------------------------------------------
-- E. get_player_card as in M4d plus trophies (closed seasons, ranks 1..3 within social.league.podium)
-- ---------------------------------------------------------------------------
create or replace function public.get_player_card(p_nickname text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  p      public.profiles;
  v_job  jsonb;
  v_pod  integer := least(3, greatest(0, public.config_double('social', '{league,podium}', 3)::integer));
begin
  perform public.require_player();
  select * into p from public.profiles x where x.id = public.player_by_handle(p_nickname);
  if p.id is null then
    perform public.api_error('player_not_found');
  end if;
  select jsonb_build_object('company_name', c.name, 'title_key', j.title_key, 'title', case when j.title_key is null then j.title end,
                            'tier', j.tier, 'since', j.started_at)
    into v_job
    from public.player_jobs j join public.companies c on c.id = j.company_id
   where j.player_id = p.id and j.status = 'active';
  return jsonb_build_object(
    'nickname',        p.nickname,
    'tag',             p.tag,
    'avatar_key',      p.avatar_key,
    'level',           p.level,
    'rank',            public.player_rich_rank(p.id),
    'net_worth_cents', public.player_net_worth_cents(p.id),
    'streak_days',     public.player_streak_days(p.id),
    'skills_learned',  (select count(*) from public.player_skills s where s.player_id = p.id)::integer,
    'branch_scores',   public.player_branch_scores(p.id),
    'top_skills',      coalesce((select jsonb_agg(jsonb_build_object('key', x.skill_key, 'tier', x.tier) order by x.tier desc, x.learned_at)
                                   from (select s.skill_key, s.learned_at, (public.skill_node(s.skill_key) ->> 'tier')::integer as tier
                                           from public.player_skills s where s.player_id = p.id
                                          order by 3 desc nulls last, s.learned_at limit 3) x), '[]'::jsonb),
    'job',             v_job,
    'company',         (select jsonb_build_object('name', c.name, 'ticker', c.ticker)
                          from public.player_companies pc join public.companies c on c.id = pc.company_id
                         where pc.founder_id = p.id and pc.status = 'active'),
    'trophies',        (select jsonb_build_object('gold',   count(*) filter (where e.rank = 1),
                                                  'silver', count(*) filter (where e.rank = 2),
                                                  'bronze', count(*) filter (where e.rank = 3))
                          from public.league_entries e join public.league_seasons ls on ls.id = e.season_id
                         where e.player_id = p.id and ls.status = 'finished' and e.rank between 1 and v_pod),
    'member_since',    p.created_at);
end;
$$;

-- ---------------------------------------------------------------------------
-- F. run_due_jobs as in M4a plus the social work (league, feed clean-up)
-- ---------------------------------------------------------------------------
create or replace function public.run_due_jobs()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- player companies: operating hours (ADR-072), then every closed quarter since their founding (ADR-057)
  v_result := v_result || jsonb_build_object('player_companies', public.player_companies_run_due());

  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- jobs: AI postings of the running quarter, wages of AI-company jobs in whole hours
  v_result := v_result || jsonb_build_object('quit_notices', public.process_quit_notices(null));
  v_result := v_result || jsonb_build_object('share_offers', public.close_due_offers(null));
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  -- artworks (ADR-080): due auctions are settled, the gallery starts the auctions of the day
  v_result := v_result || jsonb_build_object('artworks', public.artworks_run_due());

  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- weekly league and feed clean-up (ADR-088, ADR-089), throttled inside
  v_result := v_result || jsonb_build_object('social', public.social_run_due());

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.league_week_start(timestamptz)', 'public.format_growth_bps(bigint)', 'public.league_ensure_season(timestamptz)',
    'public.league_add_inflow(uuid, bigint)', 'public.league_refresh(uuid, boolean)', 'public.league_close(uuid)',
    'public.social_run_due()', 'public.league_on_vault_claim()', 'public.league_on_daily_reward()',
    'public.get_league(text, text)', 'public.get_player_card(text)', 'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array['public.get_league(text, text)', 'public.get_player_card(text)'] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261128000100_m4g_events.sql =====
-- ===== idempotent copy of migrations/20261128000100_m4g_events.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4g · 0100 · Announced events (ADR-090)
-- =============================================================================
-- Plans and resolves the rows of public.scheduled_events (created in 1100, unused until now):
--   opening_bell / closing_bell  daily at time.marketOpenHour / marketCloseHour (Europe/Berlin), informational
--   earnings      at the end of every game quarter for the events.schedule.earningsTopCompanies largest
--                 AI companies by market cap; outcome from company_quarter_reports (the earnings sentiment
--                 itself is applied by simulate_ai_companies at the quarter close, unchanged)
--   pharma_trial  per pharma AI company and quarter with events.pharmaTrial.probabilityPerQuarter,
--                 announced announceLeadQuarters ahead (scheduled in the middle of that quarter); the hidden
--                 success probability (by size class) lives in scheduled_event_secrets. Resolution mirrors
--                 resolvePharmaTrial (src/lib/sim/events.ts): the move is a real, persistent price shock;
--                 fair value, EMAs and the new security_sim_state.event_value_factor move by the same factor
--                 (fair_value_from_fundamentals multiplies by it), so value funds do not revert the jump
--   rate_decision on isRateDecisionQuarter quarters (src/lib/sim/central-bank.ts), announced once the
--                 quarter announceLeadQuarters before has ended; decidePolicyRate on the per-capita growth of
--                 the money supply (player + player-company accounts per active player) against the
--                 money_supply_snapshots row measurementWindowQuarters earlier (no such row: rate held)
-- Every event is planned at most events.schedule.horizonHours ahead and idempotently (dedupe_key).
-- run_due_jobs() calls events_run_due(): planning every 15 minutes, resolution of due events every
-- minute (late events after a downtime are resolved once), a money supply snapshot per closed quarter.
-- Holders of a pharma stock get the notification event_holding.
-- New RPC get_events(p_limit) -> {server_time, upcoming: [EVENT], recent: [EVENT]}
--   EVENT = {id, kind, importance, scheduled_at, announced_at, status, ticker, company_name, sector, outcome}
--   outcome null until resolved; bells {}; earnings {revenue_cents, net_income_cents, eps_e4,
--   revenue_change_bps, net_income_change_bps, surprise: beat|miss|inline}; pharma_trial {success, move_bps,
--   price_before_e4, price_after_e4}; rate_decision {old_bps, new_bps, money_growth_bps (null: no measurement)}
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.security_sim_state
  add column if not exists event_value_factor double precision not null default 1;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'security_sim_state_event_value_factor_check'
                    and conrelid = 'public.security_sim_state'::regclass) then
    alter table public.security_sim_state add constraint security_sim_state_event_value_factor_check
      check (event_value_factor > 0);
  end if;
end;
$$;
comment on column public.security_sim_state.event_value_factor is
  'Multiplier on the fair value from binary events (pharma trials, ADR-090), 1 = neutral. Mirrors eventValueFactor in src/lib/sim/fair-value.ts.';

alter table public.money_supply_snapshots add column if not exists active_players integer;
comment on column public.money_supply_snapshots.active_players is
  'Players with a daily login in the last centralBank.activePlayerWindowDays days when the snapshot was taken (per-capita money growth, ADR-090).';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('event_holding', 'market', 'Ereignis in deinem Depot', 'Ein angekündigtes Ereignis hat eine Aktie aus deinem Depot bewegt.',
        'notif_clock', true, false, false, 105)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Fair value with the event factor (as in M1, times security_sim_state.event_value_factor)
-- ---------------------------------------------------------------------------
create or replace function public.fair_value_from_fundamentals(p_company_id uuid)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c        public.companies;
  v_val    jsonb := coalesce(public.config_jsonb('valuation'), '{}'::jsonb);
  v_sec    jsonb;
  v_policy integer;
  v_pe     double precision;
  v_growth double precision := 0;
  v_recent numeric;
  v_prev   numeric;
  v_n      integer;
  v_macro  double precision;
  v_event  double precision;
  v_fv     double precision;
begin
  select * into c from public.companies where id = p_company_id;
  if c.id is null or c.shares_outstanding <= 0 or c.ttm_net_income_cents <= 0 then
    return null;
  end if;
  v_sec := coalesce(public.config_jsonb('sectors', array[c.sector_key]), '{}'::jsonb);
  v_pe := public.cfg_num(v_sec, '{peRatio}', coalesce((select s.base_pe from public.sectors s where s.key = c.sector_key), 15));
  select count(*), sum(x.revenue_cents) filter (where x.rn <= 4), sum(x.revenue_cents) filter (where x.rn > 4)
    into v_n, v_recent, v_prev
    from (select r.revenue_cents, row_number() over (order by gq.starts_at desc) as rn
            from public.company_quarter_reports r
            join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = c.id and r.published_at is not null
           order by gq.starts_at desc limit 8) x;
  if v_n >= 8 and v_prev > 0 then
    v_growth := v_recent / v_prev - 1;
  end if;
  select cb.policy_rate_bps into v_policy from public.central_bank_state cb where cb.id;
  v_macro := greatest(public.cfg_num(v_val, '{macroFactorMin}', 0.6), least(public.cfg_num(v_val, '{macroFactorMax}', 1.3),
               1 - public.cfg_num(v_val, '{macroSensitivityPer100Bps}', 0.04)
                 * public.cfg_num(v_sec, '{sensitivity,valuationRate}', 1)
                 * (coalesce(v_policy, 300) - public.config_double('centralBank', '{neutralRateBps}', 300)) / 100.0));
  -- binary events (pharma trials, ADR-090): the fair value follows the price shock
  select st.event_value_factor into v_event from public.security_sim_state st where st.security_id = c.security_id;
  v_fv := (c.ttm_net_income_cents::double precision / c.shares_outstanding)        -- EPS in cents
        * v_pe
        * greatest(public.cfg_num(v_val, '{growthFactorMin}', 0.6),
                   least(public.cfg_num(v_val, '{growthFactorMax}', 1.8), 1 + public.cfg_num(v_val, '{growthWeight}', 1) * v_growth))
        * v_macro
        * coalesce(v_event, 1)
        * 100;                                                                        -- cents -> e4
  return greatest(public.config_double('trading', '{minPriceE4}', 1)::bigint, round(v_fv)::bigint);
end;
$$;

-- ---------------------------------------------------------------------------
-- C. Helpers
-- ---------------------------------------------------------------------------
-- Game quarter by running index (0 = first quarter of game year 1), NULL row if it does not exist.
create or replace function public.game_quarter_by_index(p_index integer)
returns public.game_quarters
language sql
stable
security definer
set search_path = ''
as $$
  select gq.* from public.game_quarters gq
   where p_index >= 0 and gq.game_year = p_index / 4 + 1 and gq.quarter = p_index % 4 + 1;
$$;
comment on function public.game_quarter_by_index(integer) is
  'Internal (ADR-090): game quarter by running index (game_year - 1) * 4 + quarter - 1.';

-- Money supply sample (MoneySupplySample in src/lib/sim/central-bank.ts): all player and player-company
-- accounts (cash and reserve; AI companies are not part of the money supply), players with a daily login
-- in the last centralBank.activePlayerWindowDays days.
create or replace function public.events_money_sample(p_now timestamptz, out money_supply_cents bigint, out active_players integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_days integer := greatest(1, public.config_double('centralBank', '{activePlayerWindowDays}', 7))::integer;
begin
  select coalesce(sum(a.balance_cents), 0)::bigint into money_supply_cents
    from public.ledger_accounts a
    left join public.companies c on c.id = a.owner_company_id
   where a.kind in ('player_cash', 'player_reserve')
      or (a.kind in ('company_cash', 'company_reserve') and c.id is not null and not c.is_ai);
  select count(distinct dl.player_id)::integer into active_players
    from public.daily_logins dl
    join public.profiles p on p.id = dl.player_id
   where dl.login_day > (p_now at time zone 'Europe/Berlin')::date - v_days
     and dl.login_day <= (p_now at time zone 'Europe/Berlin')::date
     and not p.is_deactivated;
end;
$$;
comment on function public.events_money_sample(timestamptz) is
  'Internal (ADR-090): money supply of players and player companies, active players (central bank input).';

-- Snapshot of the money supply for the latest ended quarter (once per quarter; no backfill after a downtime).
create or replace function public.events_snapshot_money(p_now timestamptz)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_q      bigint;
  v_player bigint;
  v_comp   bigint;
  v_sample record;
  v_rows   integer;
begin
  select gq.id into v_q from public.game_quarters gq where gq.ends_at <= p_now order by gq.ends_at desc limit 1;
  if v_q is null or exists (select 1 from public.money_supply_snapshots m where m.game_quarter_id = v_q) then
    return null;
  end if;
  select coalesce(sum(a.balance_cents), 0)::bigint into v_player
    from public.ledger_accounts a where a.kind in ('player_cash', 'player_reserve');
  select * into v_sample from public.events_money_sample(p_now);
  v_comp := v_sample.money_supply_cents - v_player;
  insert into public.money_supply_snapshots (game_quarter_id, player_cents, company_cents, active_players)
  values (v_q, v_player, v_comp, v_sample.active_players)
  on conflict (game_quarter_id) do nothing;
  get diagnostics v_rows = row_count;
  return case when v_rows > 0 then v_q end;
end;
$$;
comment on function public.events_snapshot_money(timestamptz) is
  'Internal (ADR-090): money_supply_snapshots row of the latest ended quarter (players, player companies, active players).';

-- In-app notification, unless the player switched the type off (missing preference: the type's default)
create or replace function public.event_notify(p_player uuid, p_title text, p_body text, p_payload jsonb, p_link text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.notification_types t where t.key = 'event_holding') then
    return;
  end if;
  if not coalesce((select np.in_app_enabled from public.notification_preferences np
                    where np.player_id = p_player and np.type_key = 'event_holding'),
                  (select t.default_in_app from public.notification_types t where t.key = 'event_holding'), true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, 'event_holding', p_title, p_body, coalesce(p_payload, '{}'::jsonb), p_link, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;
comment on function public.event_notify(uuid, text, text, jsonb, text, text) is
  'Internal (ADR-090): event_holding notification, respecting the player''s preference.';

-- Persistent price shock of one stock by (10 000 + p_move_bps) / 10 000: quote, fair value, event factor and
-- EMAs move together (no momentum signal, no value-fund reversion), plus a price tick and the candles.
create or replace function public.event_price_shock(p_security uuid, p_move_bps integer, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_epoch   constant timestamptz := '2000-01-01 00:00:00+00';
  v_min     bigint := greatest(1, public.config_double('trading', '{minPriceE4}', 1))::bigint;
  v_mult    numeric := greatest(1, 10000 + p_move_bps)::numeric;   -- MIN_EVENT_FACTOR 0.01 at -9 900 bps
  v_factor  double precision := greatest(1, 10000 + p_move_bps)::double precision / 10000;
  q         public.security_quotes;
  v_shares  bigint;
  v_before  bigint;
  v_after   bigint;
  v_bid     bigint;
  v_ask     bigint;
  v_ref     bigint;
  v_seq     bigint;
begin
  -- same lock order as market_tick_at: sim state first, then the quote
  update public.security_sim_state st
     set fair_value_e4 = greatest(v_min, public.div_round_half_even(st.fair_value_e4::numeric * v_mult, 10000)),
         event_value_factor = st.event_value_factor * v_factor,
         ema_fast = case when st.ema_fast is null then null else st.ema_fast * v_factor end,
         ema_slow = case when st.ema_slow is null then null else st.ema_slow * v_factor end,
         updated_at = now()
   where st.security_id = p_security;
  select * into q from public.security_quotes where security_id = p_security for update;
  if not found then
    return null;
  end if;
  select c.shares_outstanding into v_shares
    from public.securities s left join public.companies c on c.id = s.company_id where s.id = p_security;
  v_before := q.last_price_e4;
  v_after := greatest(v_min, public.div_round_half_even(v_before::numeric * v_mult, 10000));
  v_bid := greatest(v_min, public.div_round_half_even(coalesce(q.bid_e4, v_before)::numeric * v_mult, 10000));
  v_ask := public.div_round_half_even(coalesce(q.ask_e4, v_before)::numeric * v_mult, 10000);
  if v_ask <= v_bid then
    v_ask := v_bid + 1;
  end if;
  v_ref := coalesce(q.prev_close_e4, v_before);
  update public.security_quotes
     set last_price_e4 = v_after, bid_e4 = v_bid, ask_e4 = v_ask,
         day_high_e4 = greatest(coalesce(day_high_e4, v_after), v_after),
         day_low_e4 = least(coalesce(day_low_e4, v_after), v_after),
         change_bps = greatest(-1000000, least(1000000, round((v_after - v_ref) * 10000.0 / greatest(1, v_ref))))::integer,
         market_cap_cents = case when v_shares is null then market_cap_cents
                                 else public.div_round_half_even(v_shares::numeric * v_after, 100) end,
         updated_at = p_now
   where security_id = p_security;

  select r.tick_seq into v_seq from public.sim_runtime r where r.id;
  insert into public.price_ticks (security_id, ts, tick_seq, price_e4, volume_e6)
  values (p_security, p_now, coalesce(v_seq, 0), v_after, 0)
  on conflict do nothing;
  insert into public.candles as c (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select p_security, iv.i, iv.b, v_before, greatest(v_before, v_after), least(v_before, v_after), v_after, 0, 1
    from (values
      ('1m'::public.candle_interval, date_bin('1 minute', p_now, v_epoch)),
      ('5m'::public.candle_interval, date_bin('5 minutes', p_now, v_epoch)),
      ('1h'::public.candle_interval, date_bin('1 hour', p_now, v_epoch)),
      ('1q'::public.candle_interval, public.quarter_bucket_start(p_now)),
      ('1y'::public.candle_interval, public.game_year_bucket_start(p_now))) as iv(i, b)
  on conflict (security_id, interval, bucket_start) do update
     set high_e4 = greatest(c.high_e4, excluded.high_e4),
         low_e4 = least(c.low_e4, excluded.low_e4),
         close_e4 = excluded.close_e4,
         tick_count = c.tick_count + 1;
  return jsonb_build_object('price_before_e4', v_before, 'price_after_e4', v_after);
end;
$$;
comment on function public.event_price_shock(uuid, integer, timestamptz) is
  'Internal (ADR-090): persistent price shock; quote, fair value, event factor and EMAs move by the same factor.';

-- ---------------------------------------------------------------------------
-- D. Planning (idempotent; p_now is the game time, tests pin it)
-- ---------------------------------------------------------------------------
create or replace function public.events_plan(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ev       jsonb := coalesce(public.config_jsonb('events'), '{}'::jsonb);
  v_cb       jsonb := coalesce(public.config_jsonb('centralBank'), '{}'::jsonb);
  v_time     jsonb := coalesce(public.config_jsonb('time'), '{}'::jsonb);
  v_horizon  timestamptz := p_now + make_interval(secs => greatest(0, public.cfg_num(v_ev, '{schedule,horizonHours}', 24)) * 3600);
  v_top      integer := greatest(0, public.cfg_num(v_ev, '{schedule,earningsTopCompanies}', 3))::integer;
  v_open_h   double precision := public.cfg_num(v_time, '{marketOpenHour}', 8);
  v_close_h  double precision := public.cfg_num(v_time, '{marketCloseHour}', 22);
  v_p_trial  double precision := public.cfg_num(v_ev, '{pharmaTrial,probabilityPerQuarter}', 0.12);
  v_lead     integer := greatest(0, public.cfg_num(v_ev, '{pharmaTrial,announceLeadQuarters}', 2))::integer;
  v_warmup   integer := public.cfg_num(v_cb, '{warmupQuarters}', 56)::integer;
  v_every    integer := greatest(1, public.cfg_num(v_cb, '{decisionEveryQuarters}', 2))::integer;
  v_cb_lead  integer := greatest(0, public.cfg_num(v_cb, '{announceLeadQuarters}', 1))::integer;
  v_day      date;
  v_at       timestamptz;
  v_bells    integer := 0;
  v_earn     integer := 0;
  v_trials   integer := 0;
  v_rates    integer := 0;
  v_rows     integer;
  v_id       uuid;
  v_cur      public.game_quarters;
  v_target   public.game_quarters;
  v_ann      public.game_quarters;
  v_idx      integer;
  v_run      bigint;
  q          record;
  r          record;
begin
  -- 1. bells (Berlin wall clock, every day)
  for v_day in
    select d::date from generate_series((p_now at time zone 'Europe/Berlin')::date::timestamp,
                                        (v_horizon at time zone 'Europe/Berlin')::date::timestamp, interval '1 day') d
  loop
    for r in select * from (values ('opening_bell'::public.scheduled_event_kind, v_open_h, 'Börsenöffnung'),
                                   ('closing_bell'::public.scheduled_event_kind, v_close_h, 'Börsenschluss')) b(kind, hour, title)
    loop
      v_at := (v_day::timestamp + make_interval(secs => r.hour * 3600)) at time zone 'Europe/Berlin';
      if v_at > p_now and v_at <= v_horizon then
        insert into public.scheduled_events (kind, title, importance, game_quarter_id, dedupe_key, announced_at, scheduled_at)
        values (r.kind, r.title, 1,
                (select gq.id from public.game_quarters gq where gq.starts_at <= v_at and gq.ends_at > v_at),
                r.kind::text || ':' || to_char(v_day, 'YYYY-MM-DD'), p_now, v_at)
        on conflict (dedupe_key) do nothing;
        get diagnostics v_rows = row_count;
        v_bells := v_bells + v_rows;
      end if;
    end loop;
  end loop;

  -- 2. earnings: the largest AI companies by market cap, once per quarter
  for q in
    select gq.* from public.game_quarters gq
     where gq.ends_at > p_now and gq.ends_at <= v_horizon
       and not exists (select 1 from public.scheduled_events e where e.kind = 'earnings' and e.game_quarter_id = gq.id)
     order by gq.ends_at
  loop
    insert into public.scheduled_events (kind, title, importance, company_id, security_id, sector_key, game_quarter_id,
                                         dedupe_key, announced_at, scheduled_at)
    select 'earnings', 'Quartalszahlen ' || x.name, 2, x.id, x.security_id, x.sector_key, q.id,
           'earnings:' || q.id || ':' || x.id, p_now, q.ends_at
      from (select c.id, c.name, c.security_id, c.sector_key
              from public.companies c
              join public.securities s on s.id = c.security_id
              join public.security_quotes sq on sq.security_id = c.security_id
             where c.is_ai and c.phase = 'listed' and s.status = 'listed'
             order by sq.market_cap_cents desc nulls last, c.ticker
             limit v_top) x
    on conflict (dedupe_key) do nothing;
    get diagnostics v_rows = row_count;
    v_earn := v_earn + v_rows;
  end loop;

  -- 3. pharma trials: one roll per pharma AI company and running quarter (rollPharmaTrialAnnouncement)
  select gq.* into v_cur from public.game_quarters gq where gq.starts_at <= p_now and gq.ends_at > p_now;
  if v_cur.id is not null then
    insert into public.job_runs (job_name, run_key, status, finished_at)
    values ('events_pharma_roll', v_cur.id::text, 'succeeded', now())
    on conflict (job_name, run_key) do nothing
    returning id into v_run;
    if v_run is not null then
      v_target := public.game_quarter_by_index((v_cur.game_year - 1) * 4 + v_cur.quarter - 1 + v_lead);
      if v_target.id is not null then
        v_at := v_target.starts_at + (v_target.ends_at - v_target.starts_at) / 2;
        for r in
          select c.id, c.name, c.security_id, c.sector_key, c.tier::text as tier
            from public.companies c join public.securities s on s.id = c.security_id
           where c.is_ai and c.phase = 'listed' and s.status = 'listed' and c.sector_key = 'pharma'
             and not exists (select 1 from public.scheduled_events e
                              where e.kind = 'pharma_trial' and e.company_id = c.id and e.status in ('scheduled', 'in_progress'))
           order by c.ticker
        loop
          if v_at > p_now and v_at <= v_horizon and random() < v_p_trial then
            v_id := null;
            insert into public.scheduled_events (kind, title, importance, company_id, security_id, sector_key, game_quarter_id,
                                                 dedupe_key, announced_at, scheduled_at)
            values ('pharma_trial', 'Studienergebnis ' || r.name, 3, r.id, r.security_id, r.sector_key, v_target.id,
                    'pharma_trial:' || r.id || ':' || v_target.id, p_now, v_at)
            on conflict (dedupe_key) do nothing
            returning id into v_id;
            if v_id is not null then
              insert into public.scheduled_event_secrets (event_id, params)
              values (v_id, jsonb_build_object('success_probability',
                        public.cfg_num(v_ev, array['pharmaTrial', 'successProbability', r.tier], 0.5)));
              v_trials := v_trials + 1;
            end if;
          end if;
        end loop;
      end if;
    end if;
  end if;

  -- 4. rate decisions (isRateDecisionQuarter, rateDecisionAnnouncementQuarter)
  for q in
    select gq.*, (gq.game_year - 1) * 4 + gq.quarter - 1 as idx from public.game_quarters gq
     where gq.ends_at > p_now and gq.ends_at <= v_horizon
     order by gq.ends_at
  loop
    v_idx := q.idx;
    if v_idx < v_warmup or v_idx % v_every <> v_every - 1 then
      continue;
    end if;
    if v_cb_lead > 0 then
      v_ann := public.game_quarter_by_index(v_idx - v_cb_lead);
      if v_ann.id is null or v_ann.ends_at > p_now then
        continue;
      end if;
    end if;
    insert into public.scheduled_events (kind, title, importance, game_quarter_id, dedupe_key, announced_at, scheduled_at)
    values ('rate_decision', 'Zinsentscheid der Zentralbank', 3, q.id, 'rate_decision:' || q.id, p_now, q.ends_at)
    on conflict (dedupe_key) do nothing;
    get diagnostics v_rows = row_count;
    if v_rows > 0 then
      v_rates := v_rates + 1;
      update public.central_bank_state set next_decision_at = q.ends_at, updated_at = now() where id;
    end if;
  end loop;

  return jsonb_build_object('bells', v_bells, 'earnings', v_earn, 'pharma_trials', v_trials, 'rate_decisions', v_rates);
end;
$$;
comment on function public.events_plan(timestamptz) is
  'Internal (ADR-090): plans bells, earnings, pharma trials and rate decisions up to events.schedule.horizonHours ahead (idempotent).';

-- ---------------------------------------------------------------------------
-- E. Resolution
-- ---------------------------------------------------------------------------
-- Rate decision (decidePolicyRate, moneyGrowthBps, annualizeGrowthBps in src/lib/sim/central-bank.ts).
create or replace function public.event_rate_decision(p_quarter_id bigint, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cb      jsonb := coalesce(public.config_jsonb('centralBank'), '{}'::jsonb);
  v_window  integer := public.cfg_num(v_cb, '{measurementWindowQuarters}', 4)::integer;
  v_qpy     double precision := greatest(1, public.config_double('time', '{quartersPerGameYear}', 4));
  v_neutral integer := public.cfg_num(v_cb, '{neutralRateBps}', 300)::integer;
  v_step    integer := public.cfg_num(v_cb, '{stepBps}', 25)::integer;
  v_maxst   integer := public.cfg_num(v_cb, '{maxStepsPerDecision}', 2)::integer;
  v_band    double precision := greatest(1, public.cfg_num(v_cb, '{toleranceBandBps}', 400));
  v_tgt     integer := public.cfg_num(v_cb, '{targetMoneyGrowthBps}', 800)::integer;
  v_minr    integer := public.cfg_num(v_cb, '{minRateBps}', 50)::integer;
  v_maxr    integer := public.cfg_num(v_cb, '{maxRateBps}', 1000)::integer;
  v_sent25  double precision := public.config_double('events', '{rateDecisionSentimentPer25Bps}', -0.1);
  q         public.game_quarters;
  v_prevq   public.game_quarters;
  v_prev    public.money_supply_snapshots;
  v_cur     record;
  v_old     integer;
  v_growth  integer;
  v_annual  integer;
  v_gap     integer;
  v_steps   integer;
  v_target  integer;
  v_towards integer;
  v_drift   integer;
  v_new     integer;
  v_factor  double precision;
begin
  select * into q from public.game_quarters where id = p_quarter_id;
  select cb.policy_rate_bps into v_old from public.central_bank_state cb where cb.id for update;
  v_old := coalesce(v_old, public.cfg_num(v_cb, '{startRateBps}', 300)::integer);

  -- money growth per active player over the measurement window; without a comparable snapshot (new database,
  -- downtime) there is no measurement and the bank holds the rate
  select * into v_cur from public.events_money_sample(p_now);
  if q.id is not null and v_window > 0 then
    v_prevq := public.game_quarter_by_index((q.game_year - 1) * 4 + q.quarter - 1 - v_window);
    if v_prevq.id is not null then
      select * into v_prev from public.money_supply_snapshots m where m.game_quarter_id = v_prevq.id;
    end if;
  end if;
  if v_prev.game_quarter_id is not null and v_prev.player_cents + v_prev.company_cents > 0
     and coalesce(v_prev.active_players, 0) > 0 and v_cur.active_players > 0 then
    -- Math.round: half up
    v_growth := floor(((v_cur.money_supply_cents::double precision / v_cur.active_players)
                       / ((v_prev.player_cents + v_prev.company_cents)::double precision / v_prev.active_players) - 1) * 10000 + 0.5);
    v_factor := greatest(0, 1 + v_growth / 10000.0);
    v_annual := floor((power(v_factor, v_qpy / v_window) - 1) * 10000 + 0.5);
  end if;

  if v_annual is null then
    v_new := v_old;
  else
    v_gap := v_annual - v_tgt;
    v_steps := trunc(v_gap / v_band)::integer;
    v_steps := least(v_maxst, greatest(-v_maxst, v_steps));
    v_target := v_old + v_steps * v_step;
    if v_steps = 0 and v_old <> v_neutral then
      v_towards := sign(v_neutral - v_old)::integer * v_step;
      v_drift := v_old + v_towards;
      -- do not overshoot the neutral rate
      v_target := case when sign(v_neutral - v_drift) = -sign(v_towards) then v_neutral else v_drift end;
    end if;
    v_new := least(v_maxr, greatest(v_minr, v_target));
  end if;

  update public.central_bank_state
     set policy_rate_bps = v_new, last_decision_at = p_now, next_decision_at = null, updated_at = now()
   where id;
  insert into public.central_bank_decisions (game_quarter_id, previous_rate_bps, new_rate_bps, money_supply_cents, statement, decided_at)
  values (q.id, v_old, v_new, v_cur.money_supply_cents,
          case when v_new > v_old then 'Die Zentralbank erhöht den Leitzins.'
               when v_new < v_old then 'Die Zentralbank senkt den Leitzins.'
               else 'Die Zentralbank lässt den Leitzins unverändert.' end, p_now);
  if v_new <> v_old then
    -- sentiment shock on every listed stock (spec 16), fair values with the new macro factor
    update public.security_sim_state st
       set sentiment = greatest(-1, least(1, st.sentiment + (v_new - v_old) / 25.0 * v_sent25))
      from public.securities s
     where s.id = st.security_id and s.kind = 'stock' and s.status = 'listed';
    perform public.recompute_fair_values();
  end if;
  return jsonb_build_object('old_bps', v_old, 'new_bps', v_new, 'money_growth_bps', v_annual);
end;
$$;
comment on function public.event_rate_decision(bigint, timestamptz) is
  'Internal (ADR-090): decidePolicyRate on the per-capita money growth; updates central_bank_state.';

-- Resolves every due event (oldest first, at most 200 per call). Earnings wait for their quarter close.
create or replace function public.events_resolve_due(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ev       jsonb := coalesce(public.config_jsonb('events'), '{}'::jsonb);
  v_min_mv   double precision := public.cfg_num(v_ev, '{pharmaTrial,minMove}', 0.5);
  v_max_mv   double precision := public.cfg_num(v_ev, '{pharmaTrial,maxMove}', 0.7);
  v_per_surp double precision := greatest(1e-9, public.cfg_num(v_ev, '{earnings,sentimentPerSurprise}', 3));
  e          record;
  v_out      jsonb;
  v_status   public.scheduled_event_status;
  v_q        public.game_quarters;
  v_rep      record;
  v_prev     record;
  v_shock    double precision;
  v_p        double precision;
  v_success  boolean;
  v_move     integer;
  v_price    jsonb;
  v_pct      text;
  h          record;
  v_done     integer := 0;
  v_waiting  integer := 0;
  v_cancel   integer := 0;
begin
  for e in
    select se.*, c.name as company_name, c.phase as company_phase, s.ticker, s.status as security_status
      from public.scheduled_events se
      left join public.companies c on c.id = se.company_id
      left join public.securities s on s.id = se.security_id
     where se.status in ('scheduled', 'in_progress') and se.scheduled_at <= p_now
     order by se.scheduled_at, se.id
     limit 200
       for update of se skip locked
  loop
    v_out := null;
    v_status := 'resolved';

    if e.kind in ('opening_bell', 'closing_bell') then
      -- informational; a bell missed by more than an hour (downtime) is dropped
      if p_now - e.scheduled_at > interval '1 hour' then
        v_status := 'cancelled';
      else
        v_out := '{}'::jsonb;
      end if;

    elsif e.kind = 'earnings' then
      select * into v_q from public.game_quarters where id = e.game_quarter_id;
      if v_q.id is not null and v_q.status <> 'closed' then
        v_waiting := v_waiting + 1;
        continue;
      end if;
      select r.revenue_cents, r.net_income_cents, r.eps_e4 into v_rep
        from public.company_quarter_reports r where r.company_id = e.company_id and r.game_quarter_id = e.game_quarter_id;
      if v_rep is null or v_rep.revenue_cents is null then
        v_status := 'cancelled';
      else
        select r.revenue_cents, r.net_income_cents into v_prev
          from public.company_quarter_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
         where r.company_id = e.company_id and gq.starts_at < v_q.starts_at
         order by gq.starts_at desc limit 1;
        -- the surprise behind the sentiment shock of simulate_ai_companies (its news effect)
        select ef.sentiment into v_shock
          from public.news_items n join public.news_item_effects ef on ef.news_item_id = n.id
         where n.company_id = e.company_id and n.game_quarter_id = e.game_quarter_id and n.category = 'earnings'
         order by n.id desc limit 1;
        v_out := jsonb_build_object(
          'revenue_cents', v_rep.revenue_cents, 'net_income_cents', v_rep.net_income_cents, 'eps_e4', v_rep.eps_e4,
          'revenue_change_bps', case when coalesce(v_prev.revenue_cents, 0) <> 0
                                     then round((v_rep.revenue_cents - v_prev.revenue_cents) * 10000.0 / abs(v_prev.revenue_cents))::bigint end,
          'net_income_change_bps', case when coalesce(v_prev.net_income_cents, 0) <> 0
                                        then round((v_rep.net_income_cents - v_prev.net_income_cents) * 10000.0
                                                   / abs(v_prev.net_income_cents))::bigint end,
          'surprise', case when coalesce(v_shock, 0) / v_per_surp > 0.05 then 'beat'
                           when coalesce(v_shock, 0) / v_per_surp < -0.05 then 'miss'
                           else 'inline' end);
      end if;

    elsif e.kind = 'pharma_trial' then
      if e.security_id is null or e.security_status is distinct from 'listed' then
        v_status := 'cancelled';
      else
        -- resolvePharmaTrial: success with the hidden probability, move uniform in [minMove, maxMove]
        select (sec.params ->> 'success_probability')::double precision into v_p
          from public.scheduled_event_secrets sec where sec.event_id = e.id;
        v_success := random() < coalesce(v_p, 0.5);
        v_move := round((v_min_mv + random() * (v_max_mv - v_min_mv)) * 10000)::integer;
        v_move := case when v_success then v_move else -v_move end;
        v_price := public.event_price_shock(e.security_id, v_move, p_now);
        v_out := jsonb_build_object('success', v_success, 'move_bps', v_move) || coalesce(v_price, '{}'::jsonb);
        v_pct := replace(to_char(abs(v_move) / 100.0, 'FM990.0'), '.', ',') || ' %';
        for h in
          select distinct p.player_id from public.positions p
           where p.security_id = e.security_id and p.status = 'open' and p.quantity_e6 > 0
        loop
          perform public.event_notify(
            h.player_id,
            case when v_success then 'Studie erfolgreich: ' else 'Studie gescheitert: ' end || e.company_name,
            e.ticker || case when v_success then ' steigt um ' else ' fällt um ' end || v_pct || '.',
            jsonb_build_object('event_id', e.id, 'kind', 'pharma_trial', 'ticker', e.ticker, 'success', v_success,
                               'move_bps', v_move),
            '/markets/' || e.ticker,
            'event:' || e.id);
        end loop;
      end if;

    elsif e.kind = 'rate_decision' then
      v_out := public.event_rate_decision(e.game_quarter_id, p_now);

    else
      v_out := '{}'::jsonb;
    end if;

    update public.scheduled_events
       set status = v_status, resolved_at = p_now, outcome = case when v_status = 'resolved' then v_out end, updated_at = now()
     where id = e.id;
    if v_status = 'resolved' then
      v_done := v_done + 1;
    else
      v_cancel := v_cancel + 1;
    end if;
  end loop;
  return jsonb_build_object('resolved', v_done, 'cancelled', v_cancel, 'waiting', v_waiting);
end;
$$;
comment on function public.events_resolve_due(timestamptz) is
  'Internal (ADR-090): resolves all due events once (late ones after a downtime too); earnings wait for the quarter close.';

-- Minute job part (called by run_due_jobs): planning every 15 minutes, resolution and money snapshot every call.
create or replace function public.events_run_due()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := public.game_now();
  v_run    bigint;
  v_result jsonb := '{}'::jsonb;
  v_snap   bigint;
begin
  insert into public.job_runs (job_name, run_key, status, finished_at)
  values ('events_plan', to_char(date_bin('15 minutes', v_now, '2000-01-01 00:00:00+00'::timestamptz) at time zone 'UTC',
                                 'YYYY-MM-DD"T"HH24:MI'), 'succeeded', now())
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('planned', public.events_plan(v_now));
    delete from public.job_runs j
     where (j.job_name = 'events_plan' and j.started_at < now() - interval '1 day')
        or (j.job_name = 'events_pharma_roll' and j.started_at < now() - interval '30 days');
  end if;
  v_snap := public.events_snapshot_money(v_now);
  if v_snap is not null then
    v_result := v_result || jsonb_build_object('money_snapshot', v_snap);
  end if;
  if exists (select 1 from public.scheduled_events e where e.status in ('scheduled', 'in_progress') and e.scheduled_at <= v_now) then
    v_result := v_result || jsonb_build_object('resolved', public.events_resolve_due(v_now));
  end if;
  return v_result;
end;
$$;
comment on function public.events_run_due() is
  'Internal (run_due_jobs, ADR-090): plans events every 15 minutes, resolves due events, money supply snapshot per quarter.';

-- ---------------------------------------------------------------------------
-- F. RPC get_events
-- ---------------------------------------------------------------------------
create or replace function public.get_events(p_limit integer default 20)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := public.game_now();
  v_limit  integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_recent interval := make_interval(secs => greatest(0, public.config_double('events', '{schedule,recentHours}', 24)) * 3600);
begin
  perform public.require_player();
  return jsonb_build_object(
    'server_time', v_now,
    'upcoming', coalesce((
      select jsonb_agg(x.j order by x.scheduled_at, x.id)
        from (select e.id, e.scheduled_at,
                     jsonb_build_object('id', e.id, 'kind', e.kind, 'importance', e.importance, 'scheduled_at', e.scheduled_at,
                                        'announced_at', e.announced_at, 'status', e.status, 'ticker', s.ticker,
                                        'company_name', c.name, 'sector', e.sector_key, 'outcome', null) as j
                from public.scheduled_events e
                left join public.companies c on c.id = e.company_id
                left join public.securities s on s.id = e.security_id
               where e.status in ('scheduled', 'in_progress')
               order by e.scheduled_at, e.id
               limit v_limit) x), '[]'::jsonb),
    'recent', coalesce((
      select jsonb_agg(x.j order by x.resolved_at desc, x.scheduled_at desc, x.id)
        from (select e.id, e.scheduled_at, e.resolved_at,
                     jsonb_build_object('id', e.id, 'kind', e.kind, 'importance', e.importance, 'scheduled_at', e.scheduled_at,
                                        'announced_at', e.announced_at, 'status', e.status, 'ticker', s.ticker,
                                        'company_name', c.name, 'sector', e.sector_key, 'outcome', e.outcome) as j
                from public.scheduled_events e
                left join public.companies c on c.id = e.company_id
                left join public.securities s on s.id = e.security_id
               where e.status = 'resolved' and e.resolved_at > v_now - v_recent
               order by e.resolved_at desc, e.scheduled_at desc, e.id
               limit v_limit) x), '[]'::jsonb));
end;
$$;
comment on function public.get_events(integer) is
  'RPC (ADR-090): {server_time, upcoming, recent}; EVENT = {id, kind, importance, scheduled_at, announced_at, status, ticker, company_name, sector, outcome}.';

-- ---------------------------------------------------------------------------
-- G. run_due_jobs: call events_run_due() before the daily maintenance
-- ---------------------------------------------------------------------------
-- Injected into the current definition instead of redefining the whole function, so that other
-- additions to run_due_jobs() (migrations of the same milestone) are kept. Idempotent; fails loudly if
-- the anchor line is missing.
do $$
declare
  v_def    text;
  v_anchor constant text := '  -- daily maintenance (first run per UTC day)';
begin
  v_def := pg_get_functiondef('public.run_due_jobs()'::regprocedure);
  if position('public.events_run_due()' in v_def) > 0 then
    return;
  end if;
  if position(v_anchor in v_def) = 0 then
    raise exception 'NEXA M4g: anchor "%" not found in run_due_jobs()', v_anchor;
  end if;
  v_def := replace(v_def, v_anchor,
    '  -- announced events (ADR-090): planning, resolution of due events, money supply snapshot' || chr(10)
    || '  v_result := v_result || jsonb_build_object(''events'', public.events_run_due());' || chr(10) || chr(10)
    || v_anchor);
  execute v_def;
end;
$$;

-- ---------------------------------------------------------------------------
-- H. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.fair_value_from_fundamentals(uuid)', 'public.game_quarter_by_index(integer)',
    'public.events_money_sample(timestamptz)', 'public.events_snapshot_money(timestamptz)',
    'public.event_notify(uuid, text, text, jsonb, text, text)', 'public.event_price_shock(uuid, integer, timestamptz)',
    'public.events_plan(timestamptz)', 'public.event_rate_decision(bigint, timestamptz)',
    'public.events_resolve_due(timestamptz)', 'public.events_run_due()', 'public.get_events(integer)',
    'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.get_events(integer) to authenticated;
end;
$$;

commit;
